# flake8: noq


import re
from itertools import chain
from .epc_section_generic import EpcSectionGeneric, EpcLine
from ..utils.logger import logger


class SectionUe(EpcSectionGeneric):
    """
    Section "Ue" is a part of epc.lua config file.
    Generated content base on ue.yaml.
    Example generated for CLOUD_R4A_CUS:

    --================================================================================
    -- UEs section
    --================================================================================
    local mcc = 244
    local mnc = 8
    local mnc_length = 2
    local msin = 8723000001
    local ip_1 = 30
    local ip_2 = 61
    local ip_3 = 0
    local ip_4 = 1
    for ue_id=1,1000 do
        exec("set_ue lmts id="..ue_id.." sec_key=000102030405060708090a0b0c0d0e0f imsi="..mcc..":"..string.format('%0'..mnc_length..'d', mnc)..":"..msin.." eea=aes eia=aes")  # noqa: E501
        exec("set_bearer id=1 ue="..ue_id.." default=on qci=9 ip="..ip_1.."."..ip_2.."."..ip_3.."."..ip_4.." trf_type=external")
        exec("set_bearer id=2 ue="..ue_id.." default=off qci=1 gbr_ul=64 gbr_dl=64 mbr_ul=64 mbr_dl=64")
        exec("set_bearer id=3 ue="..ue_id.." default=off qci=4 gbr_ul=64 gbr_dl=64 mbr_ul=64 mbr_dl=64")
        exec("set_bearer id=4 ue="..ue_id.." default=off qci=5")
        exec("set_bearer id=5 ue="..ue_id.." default=off qci=6")
        exec("set_bearer id=6 ue="..ue_id.." default=off qci=7")
        exec("set_bearer id=7 ue="..ue_id.." default=off qci=100 gbr_ul=64 gbr_dl=64 mbr_ul=64 mbr_dl=64")
        exec("set_bearer id=8 ue="..ue_id.." default=off qci=128 gbr_ul=64 gbr_dl=64 mbr_ul=64 mbr_dl=64")
        exec("set_bearer id=9 ue="..ue_id.." default=off qci=129 gbr_ul=64 gbr_dl=64 mbr_ul=64 mbr_dl=64")
        exec("set_bearer id=10 ue="..ue_id.." default=off qci=130 gbr_ul=64 gbr_dl=64 mbr_ul=64 mbr_dl=64")
        exec("set_bearer id=11 ue="..ue_id.." default=off qci=131 gbr_ul=64 gbr_dl=64 mbr_ul=64 mbr_dl=64")
        exec("set_bearer id=12 ue="..ue_id.." default=off qci=135 gbr_ul=64 gbr_dl=64 mbr_ul=64 mbr_dl=64")
        exec("set_bearer id=13 ue="..ue_id.." default=off qci=136 gbr_ul=64 gbr_dl=64 mbr_ul=64 mbr_dl=64")
        exec("set_bearer id=14 ue="..ue_id.." default=off qci=254 gbr_ul=64 gbr_dl=64 mbr_ul=64 mbr_dl=64")
        exec("set_bearer id=15 ue="..ue_id.." default=off qci=200")
        msin = msin + 1
        ip_4 = ip_4 + 1
        if ip_4 >= 256 then
            ip_3 = ip_3 + 1
            ip_4 = 0
        end
        if ip_3 >= 256 then
            ip_2 = ip_2 + 1
            ip_3 = 0
        end
        if ip_2 >= 256 then
            ip_1 = ip_1 + 1
            ip_2 = 0
        end
    end
    --================================================================================
    exec("trace protocol=nas mme=1 on")
    exec("trace protocol=s1 mme=1 on")
    exec("set_cnode")
    exec("debug_log level=5")
    exec("set_log log_to_file=on")
    exec("pgw_lmts_param bearer_activation_by_trf=on")
    exec("link_ctrl_param hb_period=180 hb_retries=10 app_type=mme")
    exec("cfg_end")
    """  # noqa
    def _prepare_section_content(self, ue_config, *args, **kwargs):
        if 'ue_nr' in ue_config:
            logger.debug("Generating NR UE Section")
            self.nr = True
            self._add_ue_nr_lines(ue_config['ue_nr'])
        else:
            logger.debug("Generating UE Section")
            self._add_ue_lines(ue_config)

    def _add_ue_nr_lines(self, ue_content):
        ue_nr_capabilities = ue_content['ue_nr_capabilities']
        ul_nat_gw = ue_content['ul_nat_gw']
        dl_nat_gw = ue_content['dl_nat_gw']
        ue_nat_ip = ue_content['ue_nat_ip']
        snssai = ue_content['snssai']
        lines = []
        lines.append(EpcLine(line="set_ue external id=1 uec=1 release=15 opc_key=0ED47545168EAFE2C39C075829A7B61F nia=null+zuc+aes+snow3g"
                                  " nea=null+zuc+aes+snow3g sec_key=0102030405060708090A0B0C0D0EFF00 suci=0:311:489:0000:0:0:021645400 mode=nr",
                             exec=True, tab_count=0))
        lines.append(EpcLine(line=f"ue_param id=1 ue_nr_capabilities={ue_nr_capabilities}", exec=True, tab_count=0))
        lines.append(EpcLine(line="set_qosflow id=1 5qi=6 default=on", exec=True, tab_count=0))
        lines.append(EpcLine(line="set_qosflow id=2 5qi=5", exec=True, tab_count=0))
        lines.append(EpcLine(line="set_qosflow id=3 5qi=1", exec=True, tab_count=0))
        lines.append(EpcLine(line="set_qosrule id=1 proto=tcp qos_flow=2", exec=True, tab_count=0))
        lines.append(EpcLine(line="set_qosrule id=2 proto=udp qos_flow=3", exec=True, tab_count=0))
        lines.append(EpcLine(line=f"nwslice_set id=1 qos_flows=1,2,3 qos_rules=1,2 snssai={snssai} default=on ue=all amf=1", exec=True, tab_count=0))
        lines.append(EpcLine(line=f"set_pdu_gateway id=1 ue_nat_ip={ue_nat_ip} dl_nat_gw={dl_nat_gw} ul_nat_gw={ul_nat_gw}", exec=True, tab_count=0))
        self._section_content.append(lines)

    def _add_ue_lines(self, ue_config):
        for ue_content in ue_config['ue'].values():
            matched_ip = re.match(r'(?P<ip_1>\d+).(?P<ip_2>\d+).(?P<ip_3>\d+).(?P<ip_4>\d+)', ue_content['ip'])
            ip_sections = {ip: matched_ip.group(ip) for ip in ('ip_1', 'ip_2', 'ip_3', 'ip_4')}

            formatted_data = {x: f'"..{x}.."' for x in chain(('ue_id', 'mcc', 'msin'), ip_sections.keys())}
            formatted_data['mnc'] = '"..string.format(\'%0\'..mnc_length..\'d\', mnc).."'

            subsection = chain(
                self._generate_locals_for_loop(ip_sections, ue_content),
                self._generate_set_ue(formatted_data, ue_content, ue_config['UE_AUTN']),
                self._generate_set_bearers(formatted_data, ip_sections, ue_content,
                                           ue_config['bearer'][ue_content['bearer']]),
                self._generate_finish_loop_lines()
            )

            self._section_content.append(subsection)

    @staticmethod
    def _generate_set_ue(formatted_data, ue_content, ue_autn):
        ue_type = 'lmts' if 'profile' in ue_content or 'pool' in ue_content else 'external'
        set_ue_line = f"set_ue {ue_type} id={formatted_data['ue_id']} sec_key={ue_autn} " \
                      f"imsi={formatted_data['mcc']}:{formatted_data['mnc']}:{formatted_data['msin']} " \
                      f"eea={ue_content['eea'].lower()} eia={ue_content['eia'].lower()}"
        return [EpcLine(line=set_ue_line, exec=True, tab_count=1)]

    @staticmethod
    def _generate_set_bearers(formatted_data, ip_sections, ue_content, bearers):
        lines = []
        for i, bearer in enumerate(bearers):
            if 'qci' not in bearer:
                continue

            default, qci = bearer['default'], bearer['qci']
            bearer_line = f"set_bearer id={i + 1} ue={formatted_data['ue_id']} default={default} qci={qci}"

            if 'ip' in ue_content and default == 'on':
                bearer_line += ' ip=' + '.'.join((formatted_data[ip] for ip in ip_sections.keys())) + ''

            keywords = ['preprovisioned', 'trf_type', 'gbr_ul', 'gbr_dl', 'mbr_ul', 'mbr_dl', 'priority',
                        'preemption', 'vulnerability', 'filter', 'precedence', 'remote_port', 'proto', 'pdn']

            for keyword in filter(lambda k: k in bearer, keywords):
                bearer_line += f" {keyword}={bearer[keyword]}"

            lines.append(EpcLine(line=bearer_line, exec=True, tab_count=1))

        return lines

    @staticmethod
    def _generate_finish_loop_lines():

        return [
            EpcLine(line="msin = msin + 1", exec=False, tab_count=1),
            EpcLine(line="ip_4 = ip_4 + 1", exec=False, tab_count=1),
            EpcLine(line="if ip_4 >= 256 then", exec=False, tab_count=1),
            EpcLine(line="ip_3 = ip_3 + 1", exec=False, tab_count=2),
            EpcLine(line="ip_4 = 0", exec=False, tab_count=2),
            EpcLine(line="end", exec=False, tab_count=1),
            EpcLine(line="if ip_3 >= 256 then", exec=False, tab_count=1),
            EpcLine(line="ip_2 = ip_2 + 1", exec=False, tab_count=2),
            EpcLine(line="ip_3 = 0", exec=False, tab_count=2),
            EpcLine(line="end", exec=False, tab_count=1),
            EpcLine(line="if ip_2 >= 256 then", exec=False, tab_count=1),
            EpcLine(line="ip_1 = ip_1 + 1", exec=False, tab_count=2),
            EpcLine(line="ip_2 = 0", exec=False, tab_count=2),
            EpcLine(line="end", exec=False, tab_count=1),
            EpcLine(line="end", exec=False, tab_count=0)
        ]

    @staticmethod
    def _generate_locals_for_loop(ip_sections, ue_content):
        matched_ueid = re.match(r'(?P<first>\d+)-(?P<last>\d+)', ue_content['ueid'])
        first_ueid, last_ueid = matched_ueid.group('first'), matched_ueid.group('last')

        lines = [EpcLine(line=f"local mcc = {ue_content['mcc']}", exec=False, tab_count=0),
                 EpcLine(line=f"local mnc = {int(ue_content['mnc'])}", exec=False, tab_count=0),
                 EpcLine(line=f"local mnc_length = {len(ue_content['mcc']) - 1}", exec=False, tab_count=0),
                 EpcLine(line=f"local msin = {ue_content['msin']}", exec=False, tab_count=0)]

        for ip_section, value in ip_sections.items():
            lines.append(EpcLine(line=f"local {ip_section} = {value}", exec=False, tab_count=0))

        lines.append(EpcLine(line=f"for ue_id={first_ueid},{last_ueid} do", exec=False, tab_count=0))
        return lines

    def _add_entry_lines(self):
        return '\n'.join((self._comment_separator(), '-- UEs section', self._comment_separator())) + '\n'

    def _add_exit_lines(self):
        if self.nr:
            end_lines = (
                EpcLine(line=self._comment_separator(), exec=False, tab_count=0),
                EpcLine(line="debug_log level=0", exec=True, tab_count=0),
                EpcLine(line="sim_debug_log level=0 mme=1", exec=True, tab_count=0),
                EpcLine(line="sim_debug_log level=0 pgw=1", exec=True, tab_count=0),
                EpcLine(line="sim_debug_log level=0 uec=1", exec=True, tab_count=0),
                EpcLine(line="sim_debug_log level=0 sgw=1", exec=True, tab_count=0),
                EpcLine(line="link_ctrl_param hb_period=5 hb_retries=5", exec=True, tab_count=0),
                EpcLine(line="sim_trace amf=1 protocol=ng on", exec=True, tab_count=0),
                EpcLine(line="sim_param_set NR_PDCP_CIPHERING=distributed", exec=True, tab_count=0),
                EpcLine(line="cfg_end", exec=True, tab_count=0),
            )
        else:
            end_lines = (
                EpcLine(line=self._comment_separator(), exec=False, tab_count=0),
                EpcLine(line="trace protocol=nas mme=1 on", exec=True, tab_count=0),
                EpcLine(line="trace protocol=s1 mme=1 on", exec=True, tab_count=0),
                EpcLine(line="set_cnode", exec=True, tab_count=0),
                EpcLine(line="debug_log level=5", exec=True, tab_count=0),
                EpcLine(line="set_log log_to_file=on", exec=True, tab_count=0),
                EpcLine(line="pgw_lmts_param bearer_activation_by_trf=on", exec=True, tab_count=0),
                EpcLine(line="link_ctrl_param hb_period=180 hb_retries=10 app_type=mme", exec=True, tab_count=0),  # TODO update tests and uncomment
                EpcLine(line="cfg_end", exec=True, tab_count=0),
            )

        return '\n' + '\n'.join(self._adjust_printing_style(end_lines)) + '\n'

    @staticmethod
    def _comment_separator():
        return f"--{'=' * 80}"
